/**
 * Shift Service
 */

import { ValidationError, NotFoundError, ConflictError } from '../domain/errors/index.js';
import { IShiftRepository } from '../domain/repositories/IShiftRepository.js';
import { GeofenceService } from './GeofenceService.js';

export class ShiftService {
  constructor(
    private readonly shiftRepository: IShiftRepository,
    private readonly geofenceService: GeofenceService
  ) {}

  async clockIn(userId: number, siteId: number, location: { latitude: number, longitude: number }) {
    // 1. Check if already clocked in
    const active = await this.shiftRepository.findActiveForGuard(userId);
    if (active) throw new ConflictError('Already clocked in to another shift');

    // 2. Validate geofence (optional but recommended)
    // const site = await this.siteRepository.findById(siteId);
    // ...

    // 3. Find scheduled shift for today
    // ... logic to match scheduled vs actual

    return this.shiftRepository.create({
      guardId: userId,
      siteId,
      actualStart: new Date(),
      status: 'clocked_in',
      clockInLocation: location
    });
  }

  async clockOut(userId: number, location: { latitude: number, longitude: number }) {
    const active = await this.shiftRepository.findActiveForGuard(userId);
    if (!active) throw new NotFoundError('No active shift found to clock out');

    return this.shiftRepository.update(active.id, {
      actualEnd: new Date(),
      status: 'clocked_out',
      clockOutLocation: location
    });
  }

  async getShift(id: number) {
    return this.shiftRepository.findById(id);
  }

  async listShifts(options: any = {}) {
    return this.shiftRepository.findAll(options);
  }
}

let instance: ShiftService | null = null;

export function initializeShiftService(repo: IShiftRepository, geofence: GeofenceService): ShiftService {
  instance = new ShiftService(repo, geofence);
  return instance;
}

export function getShiftService(): ShiftService {
  if (!instance) throw new Error('ShiftService not initialized');
  return instance;
}
